// Hot batch 273: sixty-two-instruction functions no route reaches, written by hand from `tools.disasm` and verified
// by synthetic cases (element copies and fills with nested vectors, a reference walk over 64-bit pairs, a string
// search over a table, a dispatch under a lock and two record constructors that pick a default callback).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
